arguments.command:
perl -e '
open(my $fh, "<:raw", "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat") or die;
my $data;
read($fh, $data, -s $fh);
close($fh);

# Find all occurrences of PASSWORD=
my @positions;
my $pos = 0;
while (($pos = index($data, "PASSWORD=", $pos)) != -1) {
    push @positions, $pos;
    $pos++;
}

foreach my $p (@positions) {
    my $len = 80;
    my $chunk = substr($data, $p, $len);
    print "Position $p:\n";
    print "  Hex: ", unpack("H*", $chunk), "\n";
    print "  Raw: ", $chunk, "\n\n";

    # Also extract just the printable portion after PASSWORD=
    my $pw_start = $p + 9;  # after "PASSWORD="
    my $pw_end = $pw_start;
    for (my $i = $pw_start; $i < length($data) && $i < $pw_start + 30; $i++) {
        my $b = substr($data, $i, 1);
        if ($b =~ /[A-Z0-9]/) {
            $pw_end = $i + 1;
        } else {
            last;
        }
    }
    my $pw = substr($data, $pw_start, $pw_end - $pw_start);
    print "  Password: $pw (len=", length($pw), ")\n";
}
'

