arguments.command:
perl -e '
open(my $fh, "<:raw", "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat") or die;
my $data;
read($fh, $data, -s $fh);
close($fh);

# Search for all 23-character strings starting with 8XD and ending with W54
for (my $i = 0; $i <= length($data) - 23; $i++) {
    my $candidate = substr($data, $i, 23);
    if ($candidate =~ /^8XD[A-Z0-9]{17}W54$/) {
        print "Found at offset $i: $candidate\n";
    }
}

# Also search for any string containing 8XD...W54 even if not exactly at boundaries
my $pos = 0;
while (($pos = index($data, "8XD", $pos)) != -1) {
    for my $len (10..30) {
        my $candidate = substr($data, $pos, $len);
        if ($candidate =~ /^8XD[A-Z0-9]+W54/) {
            print "Variable-length match at offset $pos, len=$len: $candidate\n";
        }
    }
    $pos++;
}
print "Done scanning.\n";
'

