# Check for ext4 superblock magic at offset 0x438
perl -e '
open(my $fh, "<:raw", "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat") or die;
my $data;
read($fh, $data, 4096);
close($fh);

# Check at offset 0x438 for ext4 magic (0xEF53, little-endian = 53 EF)
my $offset = 0x438;
my $magic = substr($data, $offset, 2);
printf "Magic at 0x438: %02x %02x\n", ord(substr($magic, 0, 1)), ord(substr($magic, 1, 1));

# Also check a few other offsets where superblocks might be
foreach my $off (0x400, 0x2000, 0x4000) {
    my $m = substr($data, $off + 0x38, 2);
    printf "Magic at 0x%x+0x38 = 0x%x: %02x %02x\n", $off, $off+0x38, ord(substr($m, 0, 1)), ord(substr($m, 1, 1));
}
'

