arguments.command:
# Let me look at the file more carefully around the PASSWORD= entry
# Get a bigger chunk from the file
perl -e '
open(my $fh, "<:raw", "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat") or die;
my $data;
read($fh, $data, -s $fh);
close($fh);

# Find PASSWORD= and show surrounding bytes
my $pos = index($data, "PASSWORD=");
if ($pos >= 0) {
    # Show 200 bytes before and after
    my $start = $pos > 200 ? $pos - 200 : 0;
    my $chunk = substr($data, $start, 500);

    # Print as hex with ASCII
    for (my $i = 0; $i < length($chunk); $i += 16) {
        my $line = substr($chunk, $i, 16);
        my $hex = join(" ", map { sprintf("%02x", ord($_)) } split(//, $line));
        $hex .= "   " x (16 - length($line));
        my $ascii = join("", map { /[[:print:]]/ ? $_ : "." } split(//, $line));
        printf "%08x  %s |%s|\n", $start + $i, $hex, $ascii;
    }
}
'

