arguments.command:
# Find ALL ZIP local file headers (PK\03\04) and central directory entries in the dat file
perl -e '
open(my $fh, "<:raw", "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat") or die;
my $data;
read($fh, $data, -s $fh);
close($fh);

my $pos = 0;
my $count = 0;
while (($pos = index($data, "PK\x03\x04", $pos)) != -1) {
    my $chunk = substr($data, $pos, 50);
    my $name_len = unpack("v", substr($chunk, 26, 2));
    my $extra_len = unpack("v", substr($chunk, 28, 2));
    my $compr_size = unpack("V", substr($chunk, 18, 4));
    my $uncompr_size = unpack("V", substr($chunk, 22, 4));
    my $name = substr($chunk, 30, $name_len);
    my $data_start = $pos + 30 + $name_len + $extra_len;
    my $file_data = substr($data, $data_start, $compr_size);

    printf "Local header %d at offset %d (0x%x):\n", $count, $pos, $pos;
    printf "  Name: %s\n", $name;
    printf "  Compressed: %d, Uncompressed: %d\n", $compr_size, $uncompr_size;
    printf "  Data: %s\n", substr($file_data, 0, 80);
    printf "  Data Hex: %s\n\n", unpack("H*", substr($file_data, 0, min(80, length($file_data))));

    $pos++;
    $count++;
}
' 2>&1

