arguments.command:
# Find ALL ZIP central directory headers (PK\01\02) and end of central directory (PK\05\06)
perl -e '
open(my $fh, "<:raw", "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat") or die;
my $data;
read($fh, $data, -s $fh);
close($fh);

# Search for all PK signatures
my %sigs = (
    "PK\x01\x02" => "Central directory header",
    "PK\x03\x04" => "Local file header", 
    "PK\x05\x06" => "End of central directory",
);

foreach my $sig (keys %sigs) {
    my $pos = 0;
    my $count = 0;
    while (($pos = index($data, $sig, $pos)) != -1) {
        my $chunk = substr($data, $pos, 80);
        printf "%s at offset %d (0x%x):\n", $sigs{$sig}, $pos, $pos;
        printf "  Hex: %s\n", unpack("H*", substr($chunk, 0, 60));
        if ($sig eq "PK\x01\x02") {
            my $name_len = unpack("v", substr($chunk, 28, 2));
            my $compr = unpack("V", substr($chunk, 20, 4));
            my $uncompr = unpack("V", substr($chunk, 24, 4));
            my $name = substr($chunk, 46, $name_len);
            printf "  Name: %s, Compr: %d, Uncompr: %d\n", $name, $compr, $uncompr;
        }
        if ($sig eq "PK\x05\x06") {
            my $total_entries = unpack("v", substr($chunk, 8, 2));
            my $cd_size = unpack("V", substr($chunk, 12, 4));
            my $cd_offset = unpack("V", substr($chunk, 16, 4));
            printf "  Total entries: %d, CD size: %d, CD offset: %d\n", $total_entries, $cd_size, $cd_offset;
        }
        $pos++;
        $count++;
    }
    printf "Found %d %s entries\n\n", $count, $sigs{$sig};
}
'

